import{_ as s,C as o,o as n,c as r,j as a,a as l,E as i,a2 as d}from"./chunks/framework.sc8Z_ZE3.js";const w=JSON.parse('{"title":"Agents, skills and tools","description":"","frontmatter":{},"headers":[],"relativePath":"agents/index.md","filePath":"agents/index.md"}'),c={name:"agents/index.md"};function h(g,e,p,u,f,m){const t=o("Badge");return n(),r("div",null,[e[0]||(e[0]=a("h1",{id:"agents-skills-and-tools",tabindex:"-1"},[l("Agents, skills and tools "),a("a",{class:"header-anchor",href:"#agents-skills-and-tools","aria-label":'Permalink to "Agents, skills and tools"'},"​")],-1)),i(t,{type:"built",text:"Built"}),e[1]||(e[1]=d(' The <strong>Agents</strong> area of a Workspace: who is connected, which agents and skills exist, and what governs them.<table tabindex="0"><thead><tr><th>Group</th><th>Pages</th></tr></thead><tbody><tr><td><strong>Clients</strong></td><td>Connected clients, Install octryx-claude</td></tr><tr><td><strong>Build</strong></td><td>Agents, Workflows, Skills</td></tr><tr><td><strong>Governance</strong></td><td>Seats &amp; data classification, Policy</td></tr><tr><td><strong>Reference</strong></td><td>Tools</td></tr></tbody></table><h2 id="connected-clients" tabindex="-1">Connected clients <a class="header-anchor" href="#connected-clients" aria-label="Permalink to &quot;Connected clients&quot;">​</a></h2><p>Every coding client connected to this Workspace and what it works on: client, work item, branch, sensitive data, last seen. <strong>Active now</strong> shows activity in the last 10 minutes; <strong>All</strong> shows every client that has not stopped. Only members of the Workspace see its agents. Admins can see and revoke members&#39; devices, but cannot send them work.</p><h2 id="install-octryx-claude" tabindex="-1">Install octryx-claude <a class="header-anchor" href="#install-octryx-claude" aria-label="Permalink to &quot;Install octryx-claude&quot;">​</a></h2><p>The install lines for macOS and Linux and for Windows (WSL2), with the client version, the package checksum, and the update and uninstall commands. See <a href="/docs/install/launcher">Launcher and devices</a>.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>A list of agents with their capability ceiling, default workflow, scope, use in the last 30 days and status; <strong>Templates</strong> offers ready-made agents. An agent&#39;s page shows its goal, tools, output format, runtime, thinking, self-review, system prompt and steps, and <strong>Test in workspace</strong>.</p><p>An agent never grants permissions: its capability is a ceiling, the workflow decides the class of work, and policies decide what is forbidden.</p><h2 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h2><p>See <a href="/docs/agents/workflow-designer">Workflow designer</a>.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>A catalog of skills: instructions and files an agent can load for a task. Tabs <strong>Catalog</strong>, <strong>Categories</strong>, <strong>Sources &amp; updates</strong> and <strong>Usage</strong>.</p><ul><li><strong>New skill</strong> or <strong>Import skill</strong>: upload a <code>SKILL.md</code> or a <code>.zip</code> (at most 5 MB and 200 files, text only), from a Git repository, or from a marketplace.</li><li>Each skill has versions with a review, the Workspaces it is available in, a security view and its usage.</li><li>Imported skills can be checked for updates manually, every 6 hours, daily or weekly.</li></ul><h2 id="seats-data-classification" tabindex="-1">Seats &amp; data classification <a class="header-anchor" href="#seats-data-classification" aria-label="Permalink to &quot;Seats &amp; data classification&quot;">​</a></h2><p>The Workspace&#39;s <a href="/docs/security/data-classes">data class</a> and whether members may use their own subscription: <strong>Allow Claude subscription (seat) sessions</strong> and <strong>Codex with your own ChatGPT subscription</strong>. By default seats are allowed for public and internal data; from confidential up, they are off. Members see this page read-only.</p><h2 id="policy" tabindex="-1">Policy <a class="header-anchor" href="#policy" aria-label="Permalink to &quot;Policy&quot;">​</a></h2><p>One read-only page with everything that limits agents here: the classification rules, seats, the allowed company models, budgets, tool rules for agent clients, and connectors. See <a href="/docs/rules/policies">Policies and four-eyes</a>.</p><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>Every tool an agent can use, with its availability and source: core tools, tools searched on demand, tools from a connection, MCP tools and database tools.</p>',22))])}const b=s(c,[["render",h]]);export{w as __pageData,b as default};
